# Try different pattern lengths and approaches

def make_grid(pattern, modertype):
    grid = [[0]*12 for _ in range(12)]
    for r in range(12):
        for c in range(12):
            idx = (r + c) % len(pattern) if modertype == 'sum' else c % len(pattern)
            grid[r][c] = pattern[idx]
    return grid

patterns = {
    '4_sum': [8, 3, 9, 4],
    '5_sum': [8, 3, 9, 4, 7],
    '4_col': [8, 3, 9, 4],
    '5_sum_input': [2, 6, 7, 8],  # from my earlier attempt
}

names = list(patterns.keys())
for name in names:
    pattern = patterns[name]
    grid = make_grid(pattern, 'sum' if '_sum' in name else 'col')
    print(f"\n{name}: {grid[0][:12]}")
    print(grid[0])
